# (north/south or east/west, not diagonal)

def is_cardinal_dir(dr, dc):
    """Check if direction is cardinal (N/S/E/W) not diagonal"""
    return (dr != 0) or (dc != 0)

def has_cardinal_2fg_neighbors(grid, r, c):
    """Check if exactly 2 FG neighbors are in cardinal directions"""
    fg_cardinal = []

    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 8:  # fg
                    if (dr != 0) or (dc != 0):  # cardinal direction
                        fg_cardinal.append((dr, dc))

    # We want exactly 2 and they must be opposite (V shape)
    if len(fg_cardinal) == 2:
        dr1, dc1 = fg_cardinal[0]
        dr2, dc2 = fg_cardinal[1]

        # They must be opposite: one is (-dr, -dc) of the other
        if (dr2 == -dr1 and dc2 == -dc1):
            return True
    return False

